scwin.closeWd = function() {
    return window.open('', '_self').close();
}
scwin.openWindow = function(url) {
    Popup = window.open(url, "Popup", 'toolbar=0,scrollbars=0,location=0,statusbar=0,menubar=0,resizable=0,width=750,height=500,left = 90,top = 90');
    Popup.focus();
}

scwin.setVal1 = function() {
    ((j) => j.length ? j : $('#mf_tbl1_container_scrollX'))($('#tbl1_container_scrollX')).animate({scrollLeft:0}, 500);
}
scwin.setVal2 = function() {
    ((j) => j.length ? j : $('#mf_tbl1_container_scrollX'))($('#tbl1_container_scrollX')).animate({scrollLeft:1000}, 500);
}
scwin.checkVal = function() {
    return (scwin.__getJq(((j) => j.length ? j : $('#mf_tbl1_head_table tr'))($('#tbl1_head_table tr')).first()).find('th').last())[0].innerText == '최종점수';
}

